def test_only_the_test_designer_may_write_the_acceptance_tests(guard, project, role):
    result = guard("Write", w47.write_input("Write", project / ACCEPTANCE_FILE), role)
    if role == support.TEST_DESIGNER:
        w47.assert_allowed(result, f"a Write to {ACCEPTANCE_FILE} by the test designer")
    else:
        w47.assert_stopped(result, f"a Write to {ACCEPTANCE_FILE} by {role}")

def test_the_engineer_s_own_acceptance_tests_stay_refused_and_runnable(world, session):
    root = world.tree(session)
    for call in (s.read(root / s.OWN_TEST_REL), s.bash(f"cat {s.OWN_TEST_REL}")):
        s.assert_refused(world.ask(call, s.ENGINEER, s.ENG, root), call, f"engineer rooted in the {session}: ")
    run = s.bash(f"python3 -m pytest {s.ENG.acceptance} -q")
    s.assert_allowed(world.ask(run, s.ENGINEER, s.ENG, root), run, f"engineer rooted in the {session}: ")

def test_the_test_designer_pattern_includes_the_acceptance_tests():
    faults = support.acceptance_faults(support.TEST_DESIGNER, _role_file(support.TEST_DESIGNER))
    assert not faults, f"{support.role_file_rel(support.TEST_DESIGNER)}: {faults}"
